import type { SynapseEnhancedHttpClient } from "../utils/http.ts";
import { validateString, validateUserId } from "../utils/validator.ts";
import type { IFriendCategoryV2 } from "../models/friend-categories.types.ts";
import { EnhancedApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";

export class FriendCategoriesApi {
    public constructor(private httpClient: SynapseEnhancedHttpClient) {}

    public async getCategories(): Promise<{
        categories: Record<string, IFriendCategoryV2>;
    }> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                categories: Record<string, IFriendCategoryV2>;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_CATEGORIES);
        return handleApiResponse(response, "Failed to get categories");
    }

    public async setCategories(categories: Record<string, { users: string[] }>): Promise<{
        categories: Record<string, { users: string[] }>;
        status: string;
    }> {
        for (const [categoryName, categoryData] of Object.entries(categories)) {
            validateString(categoryName, "categoryName", { minLength: 1, maxLength: 50 });

            if (categoryData.users) {
                categoryData.users.forEach((userId) => {
                    validateUserId(userId);
                });
            }
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                categories: Record<string, { users: string[] }>;
                status: string;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_CATEGORY_CREATE, categories);
        return handleApiResponse(response, "Failed to set categories");
    }

    public async getCategory(categoryName: string): Promise<{
        category: string;
        users: string[];
    }> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                category: string;
                users: string[];
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_CATEGORY_UPDATE.replace("{categoryName}", encodeURIComponent(categoryName)));
        return handleApiResponse(response, "Failed to get category");
    }

    public async updateCategory(
        categoryName: string,
        data: { users: string[] },
    ): Promise<{
        category_name: string;
        data: { users: string[] };
        status: string;
    }> {
        validateString(categoryName, "categoryName", { minLength: 1, maxLength: 100 });

        if (data.users) {
            data.users.forEach((userId) => {
                validateUserId(userId);
            });
        }

        const response = await this.httpClient.put<{
            status: string;
            data?: {
                category_name: string;
                data: { users: string[] };
                status: string;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_CATEGORY_UPDATE.replace("{categoryName}", encodeURIComponent(categoryName)), data);
        return handleApiResponse(response, "Failed to update category");
    }

    public async deleteCategory(categoryName: string): Promise<{
        category_name: string;
        status: string;
    }> {
        validateString(categoryName, "categoryName", { minLength: 1, maxLength: 100 });

        const response = await this.httpClient.delete<{
            status: string;
            data?: {
                category_name: string;
                status: string;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_CATEGORY_DELETE.replace("{categoryName}", encodeURIComponent(categoryName)));
        return handleApiResponse(response, "Failed to delete category");
    }

    public async addUserToCategory(
        categoryName: string,
        userId: string,
    ): Promise<{
        category_name: string;
        user_id: string;
        status: string;
    }> {
        validateString(categoryName, "categoryName", { minLength: 1, maxLength: 100 });
        validateUserId(userId);

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                category_name: string;
                user_id: string;
                status: string;
            };
            error?: string;
        }>(`${EnhancedApi.FRIENDS_CATEGORIES}/${encodeURIComponent(categoryName)}/users`, { user_id: userId });
        return handleApiResponse(response, "Failed to add user to category");
    }

    public async removeUserFromCategory(
        categoryName: string,
        userId: string,
    ): Promise<{
        category_name: string;
        user_id: string;
        status: string;
    }> {
        validateString(categoryName, "categoryName", { minLength: 1, maxLength: 100 });
        validateUserId(userId);

        const response = await this.httpClient.delete<{
            status: string;
            data?: {
                category_name: string;
                user_id: string;
                status: string;
            };
            error?: string;
        }>(`${EnhancedApi.FRIENDS_CATEGORIES}/${encodeURIComponent(categoryName)}/users`, { user_id: userId });
        return handleApiResponse(response, "Failed to remove user from category");
    }
}
